/**
 * Sodom and Gomorrah
 * ------------------
 * Abram bargains for the cities and Lot escapes as fire and brimstone fall; Lot's wife looks back and becomes a pillar of salt. Stage: a smoking plain at first light, zoar in a valley below, a faint salt-white silhouette on the ridge; Abram on a height watching the smoke rise like a furnace.
 *
 * Palette 0xd8b878 → 0x9c8456 · light: dawn · hero: pillar
 * Game beat: Guide Lot’s household away without looking back.
 *
 * Generated by scripts/add-shot-scenes.mjs from the act data and
 * the mood board in ../../art/. Composition follows the kit in
 * ./abraham-kit.js.
 */

import { THREE, createScene, cityGate, house, flame, pillar, person, birds } from './abraham-kit.js';

const BG = 0xd8b878;
const GROUND = 0x776542;

export function build(group) {
    const W = createScene(group, { seed: 2047153693, bg: BG, fogNear: 55, fogFar: 220 });

    /* light — dawn */
    W.lights({ sky: 0x9ab4d0, gnd: 0x5a5a52, hemi: 0.75, sun: 0xffd9a0, sunI: 0.95, sunPos: [-45, 16, 26] });

    W.disc([-58, 30, -145], 9, 0xffd9a0);
    W.disc([-58, 30, -155], 16, 0xffb060, 0.22);
    W.stars(60, 150, [0xcfd8e8, 0xbfd0e0], 0.55);
    const clouds = W.grp(group, [0, 0, 0], { name: 'cloud_bank' });
    [[-60, 34, -120, 24], [10, 40, -135, 30], [70, 33, -125, 22]].forEach(([x, y, z, s]) => {
        W.add(clouds, W.G('ico', 1, 1), W.mat(0xd8c8b8, { opacity: 0.5 }), [x, y, z], { s: [s, s * 0.24, s * 0.5] });
    });
    W.backdrop(clouds);

    /* ground */
    W.ground(260, 260, 0, 0, 0x776542, { amp: 0.6, j: 0.3, flat: 30, rise: (x, z) => Math.sin(x * 0.05) * Math.cos(z * 0.04) * 1.2 });

    /* hills: angular ridges on the horizon */
    const hills = W.grp(group, [0, 0, 0], { name: 'hills' });
    for (let i = 0; i < 9; i++) {
        const x = -130 + i * 32 + W.rr(-8, 8);
        W.add(hills, W.G('cone', W.rr(14, 28), W.rr(10, 24), 5), W.mat(0x594c32), [x, 0, -95 - W.rr(0, 25)], { r: [0, W.r() * 3, 0] });
    }
    W.backdrop(hills);

    /* city: gate, towers and houses on the far side */
    const city = W.grp(group, [-18, 0, -58], { name: 'city', r: [0, 0.11, 0] });
    cityGate(W, city, 0, 0, 0, 1.15, { stone: 0xa48b5a, trim: 0x5f5135 });
    for (let i = 0; i < 5; i++) {
        house(W, city, -34 + i * 17 + W.rr(-4, 4), 0, W.rr(-14, 6), 0.85 + W.r() * 0.4, { mud: 0x947d52 });
    }
    W.backdrop(city);

    /* fire: the burning mark */
    flame(W, group, -2.0, 0, 0.3, 1.1);
    W.point(0xff8a30, 2.0, 55, 0, 3, 0, 0.35);

    /* hero: the standing stone */
    pillar(W, group, 0, 0, 0, 1.15, { stone: 0x9c8456 });
    W.disc([0, 6, -12], 5, 0xffef9c, 0.3);

    /* figures */
    person(W, group, [-5, 0, 5], { robe: 0xd8b878, bend: 0.55, armR: [-0.4, 0.2], armL: [-0.3, -0.2], ry: -0.00, s: 1.11 });

    /* birds: slow circles high above */
    birds(W, group, 5, 55, { y: 26 });

    return W.finish();
}

export default { build };
